@Test
public void testReaderCacheRetries() throws IOException, InterruptedException {
    ReaderCache readerCache = new ReaderCache(Duration.standardMinutes(1), Runnable::run);
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1, reader1);
    // Same cache token should not recover the reader from the cache.
    assertNull(readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1));
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 1, reader2);
    assertEquals(reader2, readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 20));
    readerCache.cacheReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 20, reader2);
    // Stale cache token should not recover the reader from the cache.
    assertNull(readerCache.acquireReader(WindmillComputationKey.create(C_ID, KEY_1, SHARDING_KEY), 1, 3));
    verify(reader1).close();
    verify(reader2).close();
}

