    assertThat(reader.read(null, null), equalTo(testBatch));
    assertThat(reader.read(null, null), equalTo(testBatch));
    assertThat(reader.read(null, null), equalTo(testBatch));
    assertThat(reader.read(null, null), equalTo(testBatch));
    verify(base, times(1)).read(null, null);
}

