public void testRunParDoOperation() throws Exception {
    TestOutputReceiver receiver = new TestOutputReceiver(counterSet, NameContext.create("test", "test_receiver", "test_receiver", "test_receiver"));
    ParDoOperation parDoOperation = new ParDoOperation(new TestParDoFn(receiver), new OutputReceiver[] { receiver }, context);
    parDoOperation.start();
    parDoOperation.process("hi");
    parDoOperation.process("there");
    parDoOperation.process("");
    parDoOperation.process("bob");
    parDoOperation.finish();
    parDoOperation.abort();
    assertThat(receiver.outputElems, CoreMatchers.<Object>hasItems("x-start", "y-hi", "y-there", "y-", "y-bob", "z-finish", "a-aborted"));
