@Test
public void groupsValuesByWindowAndKey() {
    Instant instantA = new DateTime(2018, 1, 1, 1, 1, DateTimeZone.UTC).toInstant();
    Instant instantB = new DateTime(2018, 1, 1, 1, 2, DateTimeZone.UTC).toInstant();
    Instant instantC = new DateTime(2018, 1, 1, 1, 3, DateTimeZone.UTC).toInstant();
    IntervalWindow windowA = new IntervalWindow(instantA, instantB);
    IntervalWindow windowB = new IntervalWindow(instantB, instantC);
    when(context.getSideInput(COLLECTION_ID)).thenReturn(Arrays.asList(WindowedValue.of(KV.of("foo", 1), instantA, windowA, PaneInfo.NO_FIRING), WindowedValue.of(KV.of("baz", 2), instantA, windowA, PaneInfo.NO_FIRING), WindowedValue.of(KV.of("foo", 3), instantA, windowA, PaneInfo.NO_FIRING), WindowedValue.of(KV.of("foo", 4), instantB, windowB, PaneInfo.NO_FIRING), WindowedValue.of(KV.of("bar", 5), instantB, windowB, PaneInfo.NO_FIRING), WindowedValue.of(KV.of("foo", 6), instantB, windowB, PaneInfo.NO_FIRING)));
    BatchSideInputHandlerFactory factory = BatchSideInputHandlerFactory.forStage(EXECUTABLE_STAGE, context);
    MultimapSideInputHandler<String, Integer, IntervalWindow> handler = factory.forMultimapSideInput(TRANSFORM_ID, SIDE_INPUT_NAME, KvCoder.of(StringUtf8Coder.of(), VarIntCoder.of()), IntervalWindowCoder.of());
    Iterable<String> keysA = handler.get(windowA);
    Iterable<String> keysB = handler.get(windowB);
    assertThat(keysA, containsInAnyOrder("foo", "baz"));
    assertThat(keysB, containsInAnyOrder("foo", "bar"));
    Iterable<Integer> valuesA = handler.get("foo", windowA);
    Iterable<Integer> valuesB = handler.get("foo", windowB);
    assertThat(valuesA, containsInAnyOrder(1, 3));
    assertThat(valuesB, containsInAnyOrder(4, 6));
}

