@Test
public void testWritePutItemsWithDuplicates() {
    List<Item> items = Item.range(0, 100);
    Supplier<List<List<Item>>> captureRequests = captureBatchWriteRequests(client, req -> req.getPutRequest().getItem());
    pipeline.apply(Create.of(items)).// generate identical duplicates
    apply(ParDo.of(new AddDuplicatesDoFn(3, false))).apply(DynamoDBIO.<Item>write().withWriteRequestMapperFn(putRequestMapper).withAwsClientsProvider(StaticAwsClientsProvider.of(client)));
    pipeline.run().waitUntilFinish();
    List<List<Item>> requests = captureRequests.get();
    for (List<Item> reqItems : requests) {
        // each request is free of duplicates
        assertThat(reqItems).doesNotHaveDuplicates();
    }
    assertThat(requests.stream().flatMap(List::stream)).containsAll(items);
}

