@Test(expected = PipelineExecutionException.class)
public void testReadWithLimitExceeded() {
    when(client.listShards(any(ListShardsRequest.class))).thenThrow(LimitExceededException.builder().message("ListShards rate limit exceeded").build());
    readFromShards(identity(), ImmutableList.of());
}

private void mockRecords(List<List<Record>> data, int limit) {
    BiFunction<List<Record>, String, GetRecordsResponse.Builder> resp = (recs, it) -> GetRecordsResponse.builder().millisBehindLatest(0L).records(recs).nextShardIterator(it);
    for (int shard = 0; shard < data.size(); shard++) {
        List<Record> records = data.get(shard);
        for (int i = 0; i < records.size(); i += limit) {
            int to = Math.max(i + limit, records.size());
            String nextIt = (to == records.size()) ? "done" : shard + ":" + to;
            when(client.getRecords(argThat(hasShardIterator(shard + ":" + i)))).thenReturn(resp.apply(records.subList(i, to), nextIt).build());
        }
    }
    when(client.getRecords(argThat(hasShardIterator("done")))).thenReturn(resp.apply(ImmutableList.of(), "done").build());
}

private void mockShards(int count) {
    IntFunction<Shard> shard = i -> Shard.builder().shardId(Integer.toString(i)).build();
    List<Shard> shards = range(0, count).mapToObj(shard).collect(toList());
    when(client.listShards(any(ListShardsRequest.class))).thenReturn(ListShardsResponse.builder().shards(shards).build());
}

