    final CountingFn<PublishResponse> countingFn = new CountingFn<>();
    Write<String> snsWrite = SnsIO.<String>write().withPublishRequestBuilder(msg -> requestBuilder(msg, topicArn)).withCoder(DelegateCoder.of(defaultPublishResponse(), countingFn, x -> x));
