@Test
public void testGatherSortAndBatchFn() throws Exception {
    GatherSortCreateBatchesFn testFn = new GatherSortCreateBatchesFn(// batch bytes
    10000000, // batch up to 35 mutated cells.
    100, // batch rows
    5, // groupingFactor
    100, null);
    GatherSortCreateBatchesFn.ProcessContext mockProcessContext = Mockito.mock(ProcessContext.class);
    GatherSortCreateBatchesFn.FinishBundleContext mockFinishBundleContext = Mockito.mock(FinishBundleContext.class);
    when(mockProcessContext.sideInput(any())).thenReturn(getSchema());
    // Capture the outputs.
    doNothing().when(mockFinishBundleContext).output(mutationGroupListCaptor.capture(), any(), any());
    MutationGroup[] mutationGroups = new MutationGroup[] { // Unsorted group of 12 mutations.
    // each mutation is considered 7 cells,
    // should be sorted and output as 2 lists of 5, then 1 list of 2
    // with mutations sorted in order.
    g(m(4L)), g(m(1L)), g(m(7L)), g(m(12L)), g(m(10L)), g(m(11L)), g(m(2L)), g(del(8L)), g(m(3L)), g(m(6L)), g(m(9L)), g(m(5L)) };
    // Process all elements as one bundle.
    for (MutationGroup m : mutationGroups) {
        when(mockProcessContext.element()).thenReturn(m);
        // outputReceiver should not be called until end of bundle.
        testFn.processElement(mockProcessContext, null);
    }
    testFn.finishBundle(mockFinishBundleContext);
    verify(mockProcessContext, never()).output(any());
    verify(mockFinishBundleContext, times(3)).output(any(), any(), any());
    // Verify output are 3 batches of sorted values
    assertThat(mutationGroupListCaptor.getAllValues(), contains(Arrays.asList(g(m(1L)), g(m(2L)), g(m(3L)), g(m(4L)), g(m(5L))), Arrays.asList(g(m(6L)), g(m(7L)), g(del(8L)), g(m(9L)), g(m(10L))), Arrays.asList(g(m(11L)), g(m(12L)))));
}

